export type ProtonLoginErrorCode =
    | "INVALID_CREDENTIALS"
    | "TWO_FACTOR_REQUIRED"
    | "TWO_FACTOR_INVALID"
    | "CAPTCHA_REQUIRED"
    | "CAPTCHA_INVALID"
    | "CAPTCHA_CANCELLED"
    | "CANCELLED"
    | "NETWORK_ERROR"
    | "TIMEOUT"
    | "MISSING_EXECUTABLE"
    | "SESSION_PERSISTENCE"
    | "HELPER_ERROR"
    | "CONFIGURATION_ERROR"
    | "APP_VERSION_UNSUPPORTED"
    | "UNKNOWN";

export type ProtonSessionCheckCode = "INVALID_SESSION" | "NETWORK_ERROR" | "TIMEOUT" | "MISSING_EXECUTABLE" | "SESSION_PERSISTENCE" | "APP_VERSION_UNSUPPORTED" | "UNKNOWN";

export interface ProtonSessionCheckResult {
    valid: boolean;
    username?: string;
    expiresIn?: string;
    code?: ProtonSessionCheckCode;
    error?: string;
}

export interface ProtonLoginResult {
    success: boolean;
    username?: string;
    code?: ProtonLoginErrorCode;
    message?: string;
    error?: string;
    retryable?: boolean;
    captchaUrl?: string;
    /** `false` quando a máquina não guarda a sessão: ela vale só nesta execução. */
    persisted?: boolean;
}

export type ProtonPlanStatus = "free" | "premium" | "unknown";

export interface ProtonPlanResult {
    success: boolean;
    status: ProtonPlanStatus;
    maxTier?: number;
    planName?: string;
    planTitle?: string;
    checkedAt?: string;
    error?: string;
}

export interface ProtonOptimizationProgress {
    phase: "ping" | "catalog" | "preparing" | "testing" | "finalizing" | "completed" | "failed" | "cancelled";
    total: number;
    tested: number;
    succeeded: number;
    server?: string;
    /** Metadados públicos da rota catalogada (fase `catalog`). */
    country?: string;
    city?: string;
    tier?: string;
    load?: number;
    score?: number;
    downloadMbps?: number;
    uploadMbps?: number;
    pingMs?: number;
    status?: "testing" | "success" | "failed";
}

export interface ProtonOptimizationResult {
    success: boolean;
    server?: string;
    country?: string;
    city?: string;
    tier?: string;
    load?: number;
    score?: number;
    pingMs?: number;
    downloadMbps?: number;
    uploadMbps?: number;
    speedTested?: number;
    speedSucceeded?: number;
    endpoint?: string;
    confFile?: string;
    error?: string;
}

export interface RunConfgenOptions {
    args: string[];
    exePath?: string;
    stdin?: string;
    timeoutMs?: number;
    signal?: AbortSignal;
    onProgress?: (progress: ProtonOptimizationProgress) => void;
    log?: (level: "info" | "warn" | "error", message: string, data?: Record<string, unknown>) => void;
    runtimeDirectory?: string;
}

export interface ConfgenResult {
    code: number | null;
    stdout: string;
    stderr: string;
    json?: Record<string, unknown>;
}

// Países fora da escolha automática. Cerca de 1 min depois de ligado, o túnel passa a limitar o
// pacote interno a 1000 B. Nas rotas gratuitas do México isso chega como IP fragmentado, e até a
// 3.8.1 o WireSock gravava o checksum TCP calculado só sobre o primeiro fragmento: o Windows
// descartava o pacote e o anexo "carregava e sumia" (#373, #400). A 3.8.2.1 (WIRESOCK_VERSION em
// vpn-windows.ts) corrige o checksum (wiresock/WireSockUI#168), e rotas dos EUA também fragmentam
// (US-FREE#146 e #148 nos contadores do #408). Por isso o México voltou à escolha automática: a
// exclusão só vale com a opção protonExcludeFreeMexico ligada (protonAvoidFreeMexico aqui dentro).
// Rota paga e Linux ficam como estão, e pedir México explicitamente continua valendo.
/**
 * Sem país e com auto-ping desligado o helper não tem como escolher a rota e devolvia o erro
 * cru "countries flag is required" (#398). Sem país, a escolha automática é o único caminho
 * que funciona, então o -auto-ping vai assim mesmo; com país, a preferência é respeitada.
 */
export function protonNeedsAutoPing(options: { autoPing?: boolean; country?: string; }): boolean {
    return options.autoPing !== false || !options.country?.trim();
}

export function automaticExcludedCountries(
    options: { country?: string; freeOnly?: boolean; avoidFreeMexico?: boolean; },
    platform: NodeJS.Platform = process.platform,
): string {
    if (platform !== "win32" || options.freeOnly === false || options.avoidFreeMexico !== true) return "BR";
    const requested = (options.country ?? "").split(",").map(item => item.trim().toUpperCase());
    return requested.includes("MX") ? "BR" : "BR,MX";
}

export const MEASUREMENT_CRITERION_VERSION = 6;
const MAX_STDOUT_BYTES = 512 * 1024;
const MAX_STDERR_BYTES = 512 * 1024;
const MAX_PROTON_USERNAME_LENGTH = 320;
const GENERIC_PLAN_ERROR = "Não foi possível confirmar o plano Proton.";
const ACCOUNT_MISMATCH_ERROR = "A resposta do Proton não corresponde ao usuário solicitado.";
const LOGIN_CANCELLED_ERROR = "O login Proton foi cancelado.";
const HELPER_ERROR_MESSAGE = "O componente ProtonVPN falhou antes de concluir o login. Reinicie o Discord e tente novamente.";
const MISSING_EXECUTABLE_MESSAGE = "O componente ProtonVPN não foi encontrado nesta instalação.";
// A Proton recusa o identificador de cliente desatualizado (HTTP 422, código 5003). O helper novo
// responde APP_VERSION_UNSUPPORTED; o antigo só o texto "authentication failed with code: 5003".
// Não é senha nem sessão: só atualizar o GoLiveBypass resolve.
const APP_VERSION_UNSUPPORTED_MESSAGE = "A Proton deixou de aceitar esta versão do GoLiveBypass. Atualize o GoLiveBypass para continuar.";
const APP_VERSION_UNSUPPORTED_RE = /app_version_unsupported|with code: 50(01|03|05)\b|no longer (supported|accepts)/i;
const INVALID_CATALOG_ERROR = "O catálogo de rotas ProtonVPN retornou dados inválidos.";
const EMPTY_CATALOG_ERROR = "Nenhuma rota ProtonVPN está disponível para esta conta.";
const MANUAL_ROUTE_FAILURE_ERROR = "Não foi possível validar a rota ProtonVPN selecionada.";
/** Acima disso a medição não prova que a rota responde: vale como sem ping. */
const MAX_VALID_PING_MS = 999;
const MAX_ROUTE_TEXT_LENGTH = 200;
const SESSION_TEMP_FILE_RE = /^\.protonvpn-session-[A-Za-z0-9]+\.tmp(?:\.lock)?$/;

